"use client"

import animation from "react-useanimations/lib/fileText"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "File Text" from https://useanimations.com (MIT): https://useanimations.com/icons/file-text
export function AnimatedFileText(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
